27:  * const isMatch = globMatch('a/*');
28:  * console.log(isMatch('a\\b')); //=> false
29:  * console.log(isMatch('a/b')); //=> true
30:  *
31:  * // you can still configure the matcher function to accept windows paths
32:  * const isMatch = globMatch('a/*', { options: windows });
33:  * console.log(isMatch('a\\b')); //=> true
34:  * console.log(isMatch('a/b')); //=> true
35:  * ```
36:  * @param {String|Array} `globs` One or more glob patterns.
37:  * @param {Object=} `options`
