  assert.equal(glob.isMatch('a', '@(a|b)'), true)
  assert.equal(glob.isMatch('c', '@(a|b)'), true)
  assert.equal(glob.isMatch('a', '!(a|b)'), true)
  assert.equal(glob.isMatch('c', '!(a|b)'), true)
})

test('a leading bang negates the whole pattern', () => {
  assert.equal(glob.isMatch('a.js', '!*.js'), true)
  assert.equal(glob.isMatch('a.md', '!*.js'), true)
})

