  assert.equal(glob.isMatch('a/c', '{a,b}/c'), true)
  assert.equal(glob.isMatch('d/c', '{a,b}/c'), false)
  assert.equal(glob.isMatch('b/d', '[a-c]/d'), true)
  assert.equal(glob.isMatch('z/d', '[a-c]/d'), false)
})

